import json,math,hashlib,datetime
from pathlib import Path
root=Path(__file__).resolve().parent
runs=root.parent/'native-ui/runs'
names=['p7-baseline-ordinary-source-01','p7-baseline-ordinary-live-01','p7-baseline-input-01','p7-baseline-live-01','p7-baseline-large-source-01','p7-baseline-large-live-01']
def stats(values):
 values=sorted(values)
 return {'n':len(values),'p95Ms':values[math.ceil(len(values)*.95)-1],'maxMs':max(values),'minMs':min(values)} if values else None
rows=[]
for name in names:
 d=json.loads((runs/name/'samples.json').read_text());diag=json.loads((runs/name/'diagnostics.json').read_text());samples=d['samples'];size=d['metadata']['bytes'];backend=diag['backend'];route='ordinary EditorView' if not backend else ('memory SourceDocumentView' if size<256*1024 else 'native large-file SourceDocumentView')
 operation={kind:stats([s['frameMs'] for s in samples if s['kind']==kind and 'frameMs' in s]) for kind in ['jump','input','delete','search']}
 for temp in ['first-target','unchanged-warm','after-edit']:operation['jump:'+temp]=stats([s['frameMs'] for s in samples if s['kind']=='jump' and s.get('temperature')==temp])
 row={'run':name,'route':route,'routeEvidence':{'observedSourceDocumentView':backend,'fixtureBytes':size,'policy':'Frozen desktop-open-policy: performance at 128KiB, native-large-file threshold 256KiB. No direct native handle/private state observation; native classification inferred from observed backend + frozen open policy and actual file size.'},'metadata':d['metadata'],'complete':d.get('complete'),'samples':len(samples),'operations':operation,'openMs':next(s['ms'] for s in samples if s['kind']=='open-to-ready'),'saveMs':next(s['ms'] for s in samples if s['kind']=='save-to-ready'),'violations':d['violations'],'actualFileSha256':hashlib.sha256((runs/name/'original.md').read_bytes()).hexdigest(),'sampleSha256':hashlib.sha256((runs/name/'samples.json').read_bytes()).hexdigest(),'maxTimerGapMs':diag['maxTimerGap'],'workerErrors':diag['diagnostics']['errors']}
 row['unchangedFile']=row['actualFileSha256']==d['metadata']['sha256'];execution=root/(name+'-execution.json')
 if execution.exists():row['execution']=json.loads(execution.read_text())
 else:row['execution']={'performedBy':'root','note':'Initial source run performed before delegate took control; see native-ui run/control evidence.'}
 rows.append(row)
summary={'generatedUtc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'binarySha256':'f15c476a4f6e7b5f254e325692d57e9bfaa798580441dd3554f6c4fe1e9d802e','sourceCommit':'fa530b399a5ebbd020f9bfa7ca039378604c8282','p95Definition':'nearest-rank ceil(0.95*n); one cold/search/save/open sample is not a distribution estimate','timingDefinition':'trusted XTest keydown to observed cursor/DOM then two rAF callbacks; not physical screen presentation','runs':rows}
(root/'summary.json').write_text(json.dumps(summary,indent=2)+'\n')
lines=['# Frozen production latency baseline','',f"ELF `{summary['binarySha256']}`; source `{summary['sourceCommit']}`.",'','Six fresh-profile runs, each 20 cycles / 143 total records; all completed. Root ran the first 179219-byte source run; this delegate ran the remaining five. Exact commands, source snapshots, input hashes, logs, individual samples and violations remain preserved.','', '| Route / mode | Actual bytes | Input p95/max | Delete p95/max | Jump p95/max | First search | Open / save |','|---|---:|---:|---:|---:|---:|---:|']
for r in rows:
 def fmt(kind):
  s=r['operations'][kind];return f"{s['p95Ms']:.1f}/{s['maxMs']:.1f}"
 lines.append(f"| {r['route']} / {r['metadata']['mode']} | {r['metadata']['bytes']} | {fmt('input')} | {fmt('delete')} | {fmt('jump')} | {r['operations']['search']['maxMs']:.1f} | {r['openMs']:.1f}/{r['saveMs']:.1f} |")
lines+=['','All table times are milliseconds. p95 uses nearest rank; jumps combine 80 samples, with first-target/warm/after-edit subsets retained separately in JSON. Input and deletion each have 20 samples. Search, open and save each have one observation per run, so no statistical p95 claim is made for them.','', 'Ordinary Live EditorView failed nine 200ms operation targets: input rounds 0/1 (251/228ms), deletion rounds 0/1/2/3 (568/220/214/459ms), clean warm Home round 19 (664ms), after-edit End round 2 (276ms), after-edit Home round 4 (212ms). Its observed SourceDocumentView marker was false and timer gap reached 662ms; no worker/CSP errors were recorded. No root cause is proven. Other five runs had no 200ms input/deletion/warm-jump violation. Both native large-file first-search observations exceeded their 500ms target: source 546ms (DOM 465ms), live 566ms (DOM 499ms). These are retained failures; no rerun replaced them. The original harness exits 0 after recording budget violations, so the orchestration explicitly stopped with exit 1 on each affected run before inspection and continuation of independent cases. Full scenarios completed without harness exception; this does not make their performance targets all pass.','', 'The 179219-byte cases are memory-windowed, not ordinary EditorView: observed SourceDocumentView plus the frozen 128KiB/256KiB open policy establishes the distinction. The 65555-byte cases actually observed backend=false and exercise ordinary EditorView. For 10485779-byte cases, native routing is inferred from actual file size plus frozen policy and observed SourceDocumentView, not from backend=true alone.','', 'All six final file SHA-256 values match their original fixture hashes after reversible edits and save. WebKit reports longtask unsupported, so absence of longtask entries is not a responsiveness proof. Load and cgroup CPU/memory records remain in each samples.json. No CPU throttling counter increase was observed across the source large-file run; root cause of first-search misses is not established.','', 'Sources were minimally extended to permit an additional 65536-byte fixture; existing stress sizes, targets, cycles and event mechanics were unchanged. v1/v2 source snapshots and hashes are both retained. No product build or environment security change occurred during measurement.','', 'All owned driver groups stopped after each run; control records may show non-running zombies, not fully reaped processes. Xvfb :127 remains for root keyboard tests. Old :126 was not touched.']
(root/'README.md').write_text('\n'.join(lines)+'\n')
print('\n'.join(lines[:14]))
